import {STAGES,CARD_MAP} from './catalog.js';
import {getExpeditionCardMeta,EXPEDITION_ARCHETYPES,EXPEDITION_RELICS} from './expedition.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={battle:'臨時會議',elite:'硬仗',rest:'喘口氣',event:'辦公室插曲',boss:'最終提案'};
const symbols={battle:'⚔',elite:'✦',rest:'☕',event:'？',boss:'♛'};
const list=value=>Array.isArray(value)?value:[];
const meta=instance=>{try{const found=getExpeditionCardMeta(instance.cardId,instance.level||1);if(found)return found;}catch{}return {id:instance.cardId,name:'牌面更新了',kind:'basic',cost:99,text:'請重新整理，讀取這張牌的最新效果。',tags:[],unavailable:true};};
const bar=(now,max,label)=>`<div class="exp-health"><meter min="0" max="${max}" value="${Math.max(0,now)}" aria-label="${esc(label)} ${now} / ${max}"></meter><span>${now} / ${max}</span></div>`;
const archetypes=()=>Object.entries(EXPEDITION_ARCHETYPES).map(([id,value])=>({id,...value}));
function card(instance,{handIndex=null,busy=false,energy=99,button=false}={}){
 const data=meta(instance),cost=Number.isInteger(instance.cost)?instance.cost:data.cost,available=!busy&&!data.unavailable&&energy>=cost;
 return `<${button?'button':'article'} class="exp-card ${data.kind==='character'?'person-card':''} ${available?'':'unaffordable'}" ${button?`type="button" data-exp-play="${handIndex}" ${available?'':'disabled'} aria-label="打出${esc(data.name)}，費用 ${cost}，${esc(data.text)}"`:''}><span class="exp-card-cost" aria-label="費用 ${cost}">${cost}</span><span class="exp-card-type">${esc(data.kind==='character'?'人物':data.kind==='event'?'事件':data.kind==='item'?'道具':'基本動作')}</span><div class="exp-card-art">${data.portrait?`<img src="${esc(data.portrait)}" alt="" loading="lazy">`:`<span aria-hidden="true">${data.effect==='shield'||data.effect==='guard'?'⬡':data.effect==='heal'?'♡':data.effect==='expose'?'▤':'✦'}</span>`}</div><div class="exp-card-copy"><b>${esc(data.name)}</b><small>Lv.${instance.level||1}${list(data.tags).length?` · ${data.tags.map(esc).join('／')}`:''}</small><p>${esc(data.text)}</p>${button?`<span class="exp-card-play">${busy?'確認中…':available?'點一下出牌 ↗':data.unavailable?'請重新整理':'行動點不足'}</span>`:''}</div></${button?'button':'article'}>`;
}
function shell(exp,content,{busy=false}={}){
 const stage=STAGES[exp.stage-1],passive=EXPEDITION_ARCHETYPES[exp.archetype];
 return `<section class="expedition ${exp.phase==='battle'?'exp-is-battle':''}" aria-labelledby="exp-title"><header class="exp-header"><div><span class="eyebrow">THE MOVING DECK / 辦公室冒險</span><h1 id="exp-title">${esc(stage?.name||'今天，換你出牌。')}</h1><p>${esc(passive?.name||'')}${exp.status==='active'?' · 這一輪的牌組還在變。':''}</p></div>${exp.status==='active'?`<button class="text-button" data-exp-abandon ${busy?'disabled':''}>收牌，結束這輪 ↗</button>`:'<button class="text-button" data-exp-lobby>回到關卡清單 ↗</button>'}</header><div class="exp-dashboard"><div class="exp-player-vitals"><span>你的耐心</span>${bar(exp.hp,exp.maxHp,'你的耐心')}<small>${exp.block?`護盾 ${exp.block} · `:''}本輪活動幣 ${exp.coins||0}</small></div><ol class="exp-route-progress" aria-label="冒險進度">${Array.from({length:5},(_,index)=>`<li class="${exp.room>index?'done':''} ${exp.room===index+1?'current':''}"><span>${index===4?'♛':index+1}</span><small>${index===4?'總提案':exp.room>index?'已抵達':'未抵達'}</small></li>`).join('')}</ol></div>${content}${!['battle','finished'].includes(exp.phase)&&list(exp.log).length?`<section class="exp-log" aria-live="polite"><span class="eyebrow">JUST HAPPENED / 剛才這一站</span><ol>${list(exp.log).slice(-3).map(line=>`<li>${esc(line)}</li>`).join('')}</ol></section>`:''}${list(exp.relics).length?`<details class="exp-relics"><summary>本輪帶著的東西 · ${exp.relics.length}</summary><div>${exp.relics.map(id=>{const relic=EXPEDITION_RELICS[id];return `<article><b>${esc(relic?.name||id)}</b><p>${esc(relic?.description||'')}</p></article>`;}).join('')}</div></details>`:''}<details class="exp-deck-list"><summary>看看本輪牌組 · ${list(exp.deck).length} 張</summary><p>戰後拿到的牌只在這輪使用；永久收藏與卡片等級另外保存。</p><ul>${list(exp.deck).map(instance=>`<li><span>${esc(meta(instance).name)}</span><b>Lv.${instance.level||1} · 費用 ${meta(instance).cost}</b></li>`).join('')}</ul></details></section>`;
}
function lobby(state,{busy=false,archetype='evidence'}={}){
 const completed=list(state.campaign?.completed),active=state.expedition?.status==='active';
 return `<section class="exp-lobby"><div class="exp-lobby-heading"><span class="eyebrow">OFFICE ROGUELIKE / ${completed.length} OF 10</span><h1>這場會議，<br><em>輪到你出牌。</em></h1><p>抽到手裡的牌，才是這回合能用的本事。先擋眼前的攻勢，還是把行動點留給一串連招？打完再挑下一張牌，這輪會長成什麼樣，邊走邊決定。</p></div><div class="exp-how"><article><b>每回合 3 點行動</b><p>看手牌費用，決定順序；打完牌再結束回合。</p></article><article><b>先看對手意圖</b><p>護盾只擋這一波。佐證、抽牌與弱化可以接著用。</p></article><article><b>五個房間，一輪人生</b><p>選路、戰後選牌、休息與插曲，最後帶著自己的牌組上台。</p></article></div><section class="exp-archetype-picker" aria-labelledby="exp-archetype-title"><div><span class="eyebrow">HOW WILL YOU SURVIVE?</span><h2 id="exp-archetype-title">這輪，要靠哪種本事？</h2><p>開局仍使用你已儲存的三位人物、道具與事件卡。</p></div><div class="exp-archetypes">${archetypes().map(row=>`<button type="button" data-exp-archetype="${row.id}" aria-pressed="${archetype===row.id}" class="${archetype===row.id?'selected':''}" ${busy?'disabled':''}><span>${row.id==='evidence'?'▤':row.id==='slack'?'☕':'✦'}</span><b>${esc(row.name)}</b><p>${esc(row.description)}</p></button>`).join('')}</div></section><div class="exp-stages">${STAGES.map(stage=>{const won=completed.includes(stage.id),unlocked=stage.id===1||completed.includes(stage.id-1);return `<article class="exp-stage ${unlocked?'':'locked'}"><span class="exp-stage-number">${String(stage.id).padStart(2,'0')}</span><img src="${stage.portrait}" alt="" loading="lazy"><div><h3>${esc(stage.name)}</h3><p>${esc(stage.description)}</p><small>${won?'已通過 · 重玩不重領首勝':`首勝可領 ${stage.reward} 張券與養成碎片`}</small></div><button class="${unlocked?'primary':'secondary'}" type="button" data-exp-start="${stage.id}" ${busy||active||!unlocked?'disabled':''}>${unlocked?(won?'再闖一次':'開始這輪'):'先過前一關'} <span aria-hidden="true">↗</span></button></article>`;}).join('')}</div><p class="exp-fair-note">關卡不花抽卡券，失敗也不會失去收藏。既有通關紀錄照常保留；新一輪從目前儲存的編成開始。</p></section>`;
}
function route(exp,{busy}){
 return `<section class="exp-decision"><span class="eyebrow">NEXT ROOM / 接下來去哪？</span><h2>${exp.room?'這一站告一段落，下一間呢？':'推開門，挑一個開場。'}</h2><p>接下來的房間會改變這輪的資源與牌組。選完才揭曉這次遭遇。</p><div class="exp-room-options">${list(exp.roomChoices).map((choice,index)=>`<button type="button" data-exp-room="${index}" ${busy?'disabled':''}><span class="exp-room-symbol" aria-hidden="true">${symbols[choice.kind]||'？'}</span><small>${esc(names[choice.kind]||'下一個房間')}</small><h3>${esc(choice.title)}</h3><p>${esc(choice.description)}</p><b>就走這邊 ↗</b></button>`).join('')}</div></section>`;
}
function battle(exp,{busy}){
 const b=exp.battle,e=b.enemy,intent=e.intent||{},remaining=b.energy??0;
 return `<section class="exp-battle-board"><div class="exp-battle-top"><span>第 ${b.turn} / 20 回合</span><span class="exp-energy"><b>${remaining}</b> / ${b.maxEnergy||3} 行動點</span></div><div class="exp-enemy"><div class="exp-enemy-portrait">${e.portrait?`<img src="${esc(e.portrait)}" alt="${esc(e.name)}">`:'<span aria-hidden="true">♛</span>'}</div><div class="exp-enemy-info"><span class="eyebrow">THE OTHER SIDE</span><h2>${esc(e.name)}</h2>${bar(e.hp,e.maxHp,'對手耐心')}<div class="exp-enemy-tags">${e.block?`<span>護盾 ${e.block}</span>`:''}${e.exposed?`<span>佐證 ${e.exposed}</span>`:''}${e.weak?`<span>弱化 ${e.weak}</span>`:''}</div></div><aside class="exp-intent" aria-label="對手下一步"><span>對手下一步</span><b>${esc(intent.label||'準備中')}</b><p>${intent.damage?`攻勢 ${intent.damage}`:''}${intent.block?`${intent.damage?' · ':''}護盾 ${intent.block}`:''}${intent.heal?` · 恢復 ${intent.heal}`:''}</p><small>結束你的回合後執行。</small></aside></div>${b.modifierLabel?`<p class="exp-room-modifier">${esc(b.modifierLabel)}</p>`:''}<div class="exp-turn-note"><b>手牌就是你的選項。</b><span>可連續出牌；行動點不足時，仍可直接結束回合。護盾擋完這一波就會清空。</span></div></section><section class="exp-hand-section" aria-labelledby="exp-hand-title"><div class="exp-hand-heading"><h2 id="exp-hand-title">手裡的牌 <small>${list(b.hand).length} 張</small></h2><button class="primary exp-end-turn" type="button" data-exp-end-turn ${busy?'disabled':''}>結束回合 <span>→</span></button></div><div class="exp-hand">${list(b.hand).map((instance,index)=>card(instance,{handIndex:index,busy,energy:remaining,button:true})).join('')||'<p class="exp-empty-hand">手牌打完了。結束回合，看看下一手能接出什麼。</p>'}</div><div class="exp-piles">${[['drawComposition','抽牌堆',b.drawCount],['discard','棄牌堆',b.discardCount],['exhaust','本場移除',b.exhaustCount]].map(([key,label,count])=>`<details><summary>${label} · ${count??list(b[key]).length}</summary><p>${key==='drawComposition'?'只列出剩餘牌的組成，不代表抽牌順序。':'這一堆目前放著的牌。'}</p><ul>${list(b[key]).map(instance=>`<li>${esc(meta(instance).name)} <small>Lv.${instance.level||1}</small></li>`).join('')||'<li>目前沒有牌。</li>'}</ul></details>`).join('')}</div></section><section class="exp-log" aria-live="polite" aria-atomic="false"><span class="eyebrow">JUST HAPPENED / 剛才這一波</span><ol>${list(b.log||b.notes).slice(-5).map(line=>`<li>${esc(line)}</li>`).join('')}</ol></section>`;
}
function reward(exp,{busy}){
 return `<section class="exp-decision"><span class="eyebrow">ONE MORE CARD / 戰後選牌</span><h2>帶走一張，下一場接著用。</h2><p>想一想這輪缺的是傷害、防守，還是把牌接起來的那一手。這些是本輪借用的牌，不會加入永久收藏。</p><div class="exp-reward-cards">${list(exp.rewardChoices).map((instance,index)=>`<div>${card(instance)}<button class="primary" type="button" data-exp-reward="${index}" ${busy?'disabled':''}>加進本輪牌組 ↗</button></div>`).join('')}</div><button class="text-button" type="button" data-exp-reward="3" ${busy?'disabled':''}>這次不拿，讓牌組薄一點 →</button></section>`;
}
function rest(exp,{busy}){
 return `<section class="exp-decision"><span class="eyebrow">TAKE A BREATH / 工作空檔</span><h2>補耐心，還是磨一張好牌？</h2><p>休息與升級擇一，選好就往下一間走。</p><div class="exp-rest-options"><article><span aria-hidden="true">☕</span><h3>先讓自己回過神。</h3><p>恢復 26 點本輪耐心；這是卡牌冒險裡的休息。</p><button class="primary" type="button" data-exp-rest-heal ${busy?'disabled':''}>休息一下 →</button></article><article><span aria-hidden="true">✦</span><h3>把一張牌練順。</h3><label>這次升級哪張牌？<select id="exp-upgrade-card" ${busy?'disabled':''}>${list(exp.deck).map((instance,index)=>({instance,index})).filter(({instance})=>(instance.level||1)<5).map(({instance,index})=>`<option value="${index}">${esc(meta(instance).name)} · Lv.${instance.level||1}</option>`).join('')||'<option>每張牌都已練滿</option>'}</select></label><p>花費 6 枚本輪活動幣，只提升這輪使用的版本。</p><button class="secondary" type="button" data-exp-rest-upgrade ${busy||(exp.coins||0)<6||!list(exp.deck).some(card=>(card.level||1)<5)?'disabled':''}>花 6 枚，練這張 →</button></article></div></section>`;
}
function event(exp,{busy}){
 const scene=exp.event||{};
 return `<section class="exp-decision exp-social-event"><span class="eyebrow">OFFICE INCIDENT / 轉角有事</span><h2>${esc(scene.title)}</h2><p>${esc(scene.body)}</p><div class="exp-room-options">${list(scene.choices).map((choice,index)=>`<button type="button" data-exp-event="${index}" ${busy||(choice.cost||0)>(exp.coins||0)?'disabled':''}><small>0${index+1}</small><h3>${esc(choice.title)}</h3><p>${esc(choice.description)}</p><b>就這樣辦 ↗</b></button>`).join('')}</div></section>`;
}
function finished(exp,{busy}){
 const won=exp.status==='won',reward=exp.reward||{};
 return `<section class="exp-finished ${won?'won':''}" role="status"><span class="exp-finish-symbol" aria-hidden="true">${won?'✦':'☕'}</span><span class="eyebrow">${won?'MEETING ADJOURNED / 這輪過關':'LET’S TRY ANOTHER WAY / 這輪先收牌'}</span><h2>${won?'這回，願景真的被你打完了。':exp.status==='abandoned'?'你收好卡片，先替自己留點空白。':'耐心見底，這場先散會。'}</h2><p>${esc(won?'這輪借用的牌、活動幣與遺物留在本次紀錄，永久收藏照常保留。':typeof exp.summary==='string'?exp.summary:exp.summary?.body||'下一輪可以換一種路線，也可以帶另一隊同事上場。')}</p>${won?`<div class="exp-prize"><b>${reward.firstClear?'首次通過':'再次通過'}</b><span>${reward.firstClear?`＋${reward.tickets||0} 張券 · ＋${reward.shards||0} 碎片`:'這關首勝已領過，本次不重複發放。'}</span></div>`:''}<div class="exp-finish-actions"><button type="button" class="primary" data-exp-lobby ${busy?'disabled':''}>看看下一關 →</button><button type="button" class="secondary" data-exp-start="${exp.stage}" ${busy?'disabled':''}>同一關，換種打法 ↻</button></div></section>`;
}

export function renderExpeditionV72(state,options={}){
 const exp=options.showLobby?null:state?.expedition;
 if(!exp)return lobby(state,options);
 if(exp.status!=='active')return shell(exp,finished(exp,options),options);
 const render={route,battle,reward,rest,event}[exp.phase];
 return shell(exp,render?render(exp,options):'<p role="status">正在整理這輪的牌，請重新連線確認。</p>',options);
}
